import{_ as e}from"./chunks/cngal-background-logo.CTvRSuWB.js";import{_ as t,o as a,c as r,a5 as n}from"./chunks/framework.BEZBAInb.js";const g=JSON.parse('{"title":"About Konado","description":"","frontmatter":{"title":"About Konado","order":1},"headers":[],"relativePath":"en/latest/introduction/konado.md","filePath":"en/latest/introduction/konado.md","lastUpdated":1788455378000}'),i={name:"en/latest/introduction/konado.md"};function s(d,o,c,l,h,p){return a(),r("div",null,[...o[0]||(o[0]=[n('<h1 id="about-konado" tabindex="-1">About Konado <a class="header-anchor" href="#about-konado" aria-label="Permalink to &quot;About Konado&quot;">​</a></h1><h2 id="project-overview" tabindex="-1">Project Overview <a class="header-anchor" href="#project-overview" aria-label="Permalink to &quot;Project Overview&quot;">​</a></h2><p>Konado is a visual novel engine framework based on Godot Engine and driven by the open-source community. We are committed to providing developers with an efficient and convenient visual novel development experience, helping creators quickly build high-quality visual novel works and empowering creative production. We pursue friendlier and more efficient tools so game creators can focus on storytelling and artistic expression instead of getting trapped in implementation details.</p><h2 id="project-honors" tabindex="-1">Project Honors <a class="header-anchor" href="#project-honors" aria-label="Permalink to &quot;Project Honors&quot;">​</a></h2><ul><li>Konado has been included in the &quot;Plugins and scripts&quot; section of Godot Engine&#39;s official <a href="https://github.com/godotengine/awesome-godot" target="_blank" rel="noreferrer">awesome-godot</a> project as one of the recommended plugins.</li><li>Konado was honored as one of the <a href="https://atomgit.com/GitCode/G-Star100" target="_blank" rel="noreferrer">2025 AtomGit Top 100 Open Source Projects</a> and has been included in the <a href="https://gstar-landscape.gitcode.com/?item=%E9%9F%B3%E8%A7%86%E9%A2%91-%E5%9B%BE%E5%BD%A2-%E6%B8%B8%E6%88%8F-3d--%E6%B8%B8%E6%88%8F%E5%BC%95%E6%93%8E-unity-unreal-godot--konado" target="_blank" rel="noreferrer">AtomGit G-Star Landscape 3.0</a> ecosystem map.</li></ul><h2 id="project-contributors" tabindex="-1">Project Contributors <a class="header-anchor" href="#project-contributors" aria-label="Permalink to &quot;Project Contributors&quot;">​</a></h2><p>The contributor chart below is generated by <a href="https://contrib.rocks" target="_blank" rel="noreferrer">contrib.rocks</a> and updates project contributor information in real time.</p><picture><source media="(prefers-color-scheme: dark)" srcset="https://contrib.rocks/image?repo=godothub/konado&amp;theme=dark"><source media="(prefers-color-scheme: light)" srcset="https://contrib.rocks/image?repo=godothub/konado"><img alt="Contributors" src="https://contrib.rocks/image?repo=godothub/konado"></picture><h2 id="github-star-history" tabindex="-1">GitHub Star History <a class="header-anchor" href="#github-star-history" aria-label="Permalink to &quot;GitHub Star History&quot;">​</a></h2><picture><source media="(prefers-color-scheme: dark)" srcset="https://api.star-history.com/svg?repos=godothub/konado&amp;type=date&amp;theme=dark&amp;legend=top-left"><source media="(prefers-color-scheme: light)" srcset="https://api.star-history.com/svg?repos=godothub/konado&amp;type=date&amp;legend=top-left"><img alt="Star History Chart" src="https://api.star-history.com/svg?repos=godothub/konado&amp;type=date&amp;legend=top-left"></picture><h2 id="atomgit-star-history" tabindex="-1">AtomGit Star History <a class="header-anchor" href="#atomgit-star-history" aria-label="Permalink to &quot;AtomGit Star History&quot;">​</a></h2><p><img src="https://atomgit.com/godothub/konado/starcharts.svg?variant=adaptive" alt="AtomGit Star History"></p><h2 id="sponsor-us" tabindex="-1">Sponsor Us <a class="header-anchor" href="#sponsor-us" aria-label="Permalink to &quot;Sponsor Us&quot;">​</a></h2><p>If you like the Konado project and want to support our work, you are welcome to sponsor us through the following channel:</p><ul><li><a href="https://afdian.com/item/52230b2860a011f083ef52540025c377" target="_blank" rel="noreferrer">Afdian</a></li></ul><h2 id="contact-us" tabindex="-1">Contact Us <a class="header-anchor" href="#contact-us" aria-label="Permalink to &quot;Contact Us&quot;">​</a></h2><p>If you are interested in the Konado project, you are welcome to join our QQ channel group and discuss Konado&#39;s future direction with us:</p><ul><li>QQ channel group: <a href="https://pd.qq.com/g/godot" target="_blank" rel="noreferrer">https://pd.qq.com/g/godot</a></li></ul><p>If you have issue feedback or feature suggestions, please submit an <a href="https://github.com/godothub/konado/issues" target="_blank" rel="noreferrer">Issue</a> in the Konado project repository.</p><p>For other questions, please email us at <a href="mailto:konado@godothub.com" target="_blank" rel="noreferrer">konado@godothub.com</a>.</p><h2 id="acknowledgements" tabindex="-1">Acknowledgements <a class="header-anchor" href="#acknowledgements" aria-label="Permalink to &quot;Acknowledgements&quot;">​</a></h2><p><a href="https://www.cngal.org" target="_blank" rel="noreferrer"><img src="'+e+'" alt="CNGAL"></a></p>',22)])])}const b=t(i,[["render",s]]);export{g as __pageData,b as default};
